section.sourcecode:
module example-foomod {

  namespace "http://example.com/foomod";

  prefix "foomod";

  container top {
    leaf foo {
      type uint8;
    }
  }
}

module example-barmod {

  namespace "http://example.com/barmod";

  prefix "barmod";

  import example-foomod {
    prefix "foomod";
  }

  augment "/foomod:top" {
    leaf bar {
      type boolean;
    }
  }
}

container bar {
  leaf foo {
    type uint8;
  }
}

list bar {
  key foo;
  leaf foo {
    type uint8;
  }
  leaf baz {
    type string;
  }
}

module example-mod {
  ...
  import ietf-interfaces {
    prefix if;
  }
  ...
  leaf type {
    type identityref {
      base "if:interface-type";
    }
  }
}

leaf bar {
  type union {
    type uint16;
    type string;
  }
}
